-- Batch 11: verified source-bounded corrections to prognostic/time-lord terminology.
-- Directly inspected Lilly Christian Astrology Book III pp. 501–502, 507–508, 708–716, 727–728, 733–734.
-- Append-only lexicography: all existing source interpretations and numerical reference schemes retained.
PRAGMA foreign_keys=ON;

UPDATE terms SET short_definition='A predictive direction of a significator toward contact with a promittor under the primary rotation of the sphere, with the resulting arc converted into time by a specified historical key or method.',editorial_notes='Batch 11: corrected source-specific timing or directional definition.' WHERE slug='primary-direction';
UPDATE terms SET short_definition='In primary directions, the promittor (promissor) is the planet, aspect or other point whose influence is brought into contact with the significator; these are roles within the specific direction, not permanent classes of planets.',editorial_notes='Batch 11: corrected source-specific timing or directional definition.' WHERE slug='promittor';
UPDATE terms SET short_definition='Lilly’s method of adjusting an estimated birth time against dated past life events by matching primary directions involving the Ascendant or Midheaven and their promittors (*Christian Astrology*, Book III, pp. 507–508).',editorial_notes='Batch 11: corrected source-specific timing or directional definition.' WHERE slug='rectification-by-accidents';
UPDATE term_article_sections SET heading='Lilly''s thirteen equal profectional months',body='Lilly assigns one sign to each monthly stage and divides the solar-return year into thirteen equal profectional months (*Christian Astrology*, Book III, p. 716). The first begins with the annual profection sign. These are not calendar months. His definition should not silently replace a different author''s division of the year.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='monthly-profection') AND section_key='variants';
UPDATE term_article_sections SET heading='The yearly advance and the original longitude',body='In Lilly''s annual profection, the reference point moves thirty degrees—one whole sign—during each solar year, preserving its original degree within the new sign. He begins the profectional year at the Sun''s exact return to its natal place and repeats the sign cycle every twelve years (*Christian Astrology*, Book III, pp. 715–716). The familiar whole-sign version need not exhaust other authors'' procedures.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='profection') AND section_key='mechanism';
UPDATE term_article_sections SET heading='The method determines which planet governs',body='Lilly explicitly identifies the Lord of the Year with the ruler of the sign that ascends by annual profection; he also subdivides the year if the moving profected degree leaves that ruler''s sign. In his example, Jupiter rules the portion in Pisces and Mars the remainder in Aries (*Christian Astrology*, Book III, p. 727). This is Lilly''s profectional use of the title; a separate annual-revolution doctrine may determine its ruler differently.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='lord-of-year') AND section_key='role-not-formula';
UPDATE term_article_sections SET heading='Radix and annual figures are both considered',body='Lilly compares the annual ruler''s condition in the radix, in the profectional figure and in the Sun''s annual revolution, rather than reading the profectional ruler''s dignity in isolation (*Christian Astrology*, Book III, pp. 727–728). The evaluation may change when natal strength and annual condition disagree, so activation is not a substitute for judging condition.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='lord-of-year') AND section_key='natal-condition';
UPDATE term_article_sections SET heading='Different ascensions and keys in Lilly''s account',body='In Lilly''s discussion of Ptolemy''s directional time measure, the Ascendant is advanced by oblique ascensions appropriate to the birthplace, whereas the Midheaven is advanced by right ascensions. He reports the equatorial degree-to-year key and then discusses alternative measures associated with Maginus and Naibod (*Christian Astrology*, Book III, pp. 708–713). Those alternatives should not be hidden beneath a single universal calculation.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='primary-direction') AND section_key='geometry';
UPDATE term_article_sections SET heading='Lilly''s septennial sequence has its own scale',body='Lilly calls the rulers of successive seven-year spans the Lords of the Alfridary. His diurnal succession begins Sun, Venus and Mercury; his nocturnal succession begins Moon, Saturn and Jupiter (*Christian Astrology*, Book III, p. 733). This is distinct from the major-period lengths and subdivisions of Firdaria. A shared time-lord purpose does not make the systems interchangeable.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='alfridary') AND section_key='not-firdaria';
UPDATE term_article_sections SET heading='An exact solar return, not a symbolic sign advance',body='Lilly calculates the revolution for the moment when the Sun reaches exactly the longitude it held in the radix, including degree and minute (*Christian Astrology*, Book III, p. 734). Profection instead advances a reference point at a prescribed symbolic rate. The two can be interpreted together while remaining mathematically different procedures.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='solar-revolution') AND section_key='not-profection';
UPDATE term_article_sections SET heading='Historical year assignments and authorial reservations',body='Year-giving doctrines assign numerical durations to a qualifying Alcochoden and then modify them according to its condition and other testimonies. Lilly records the procedure but expresses dissatisfaction with the certainty of Alcochoden, Hyleg and Anareta judgments (*Christian Astrology*, Book III, Chapter CIV). Their technical terms can be explained without presenting their longevity estimates as clinical or factual forecasts.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='alcochoden') AND section_key='limits';
UPDATE term_article_sections SET heading='Lilly distinguishes the scrutiny from Animodar',body='Lilly describes the Trutine as relating the Moon''s place at birth to the Ascendant at conception, or the inverse relationship in a proposed conception figure. He reports practical limitations and says it often gives him no more than the Ascendant sign or a near degree (*Christian Astrology*, Book III, pp. 501–502). Animodar begins from a different prenatal-syzygy procedure and should not be merged with it.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='trutine-of-hermes') AND section_key='ontology-distinction';
UPDATE term_article_sections SET heading='Year values are inputs to different procedures',body='The numerical year classes associated with each planet can enter distinct historical calculations, including the year-giving doctrine of the Alcochoden. A table records those assigned quantities; how a source chooses and adjusts a particular class depends on that procedure. This distinction prevents the numbers from being mistaken for the chronological order of Firdaria or an automatic life-expectancy prediction.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='planetary-years') AND section_key='procedure-dependent';
UPDATE term_article_sections SET heading='Indication and the usefulness of preparation',body='Abū Maʿshar''s defence of foreknowledge distinguishes preparing for an indicated event from claiming that every indicated event is absolutely compelled. He discusses avoidance, moderation of harm, orderly preparation and timely advantage. These are claims about the practical use of astrological judgment in his philosophy, not empirical guarantees of infallible prediction.',editorial_notes='Batch 11: edited original section with source-bounded timing evidence.' WHERE term_id=(SELECT id FROM terms WHERE slug='foreknowledge') AND section_key='not-necessity';
UPDATE term_articles SET intro='Monthly profection moves a selected natal point through the signs at a monthly time scale, within the yearly cycle. Lilly''s version starts at the annual profected sign and divides the solar year into thirteen equal profectional intervals rather than twelve calendar months.',editorial_notes='Batch 11: condensed historical technique introduction without changing methods or numeric data.' WHERE term_id=(SELECT id FROM terms WHERE slug='monthly-profection');
UPDATE term_articles SET intro='An annual revolution is a solar-return figure for the Sun''s return to a specified starting longitude. Bonatti distinguishes a natal return from the mundane world-year figure, whose starting longitude is the first point of Aries. The topic and chosen reference longitude identify the specific revolution.',editorial_notes='Batch 11: condensed historical technique introduction without changing methods or numeric data.' WHERE term_id=(SELECT id FROM terms WHERE slug='annual-revolution');
UPDATE term_articles SET intro='A Solar Revolution, or Solar Return, is erected for the Sun''s precise recurrence at its natal zodiacal longitude. It is a return chart, not the symbolic advancement used in annual profection; different historical annual techniques may be combined without making their calculations identical.',editorial_notes='Batch 11: condensed historical technique introduction without changing methods or numeric data.' WHERE term_id=(SELECT id FROM terms WHERE slug='solar-revolution');
